import 'dart:async';

import 'package:jackdaw/jackdaw.dart';
import 'package:jackdaw_native/src/native/utf8_accumulator.dart';

/// The Dart side of one running native generation.
final class NativeRun {
  /// Creates a run that delivers events to [controller].
  factory(StreamController<ModelEvent> controller) = NativeRun._;

  new _(this.controller);

  /// Receives the run's events.
  final StreamController<ModelEvent> controller;

  final Utf8Accumulator _text = Utf8Accumulator();

  /// Adds generated bytes, emitting only complete characters.
  void addBytes(List<int> bytes) {
    final text = _text.add(bytes);
    if (text.isNotEmpty) controller.add(TextDelta(text));
  }

  /// Ends the run with [reason] and [usage].
  void finish(FinishReason reason, Usage usage) {
    final rest = _text.flush();
    if (rest.isNotEmpty) controller.add(TextDelta(rest));
    controller
      ..add(FinishEvent(reason: reason, usage: usage))
      ..close().ignore();
  }

  /// Ends the run with [error].
  void fail(Object error) {
    controller
      ..addError(error)
      ..close().ignore();
  }
}
